sealed interface Memo {
    data class Ok(val node: Node, val next: Int) : Memo
    object Fail : Memo
}

class Parser {
    private val memo = HashMap<Long, Memo>()
    fun rule(ruleId: Int, pos: Int): Memo {
        val key = (ruleId.toLong() shl 32) or pos.toLong()
        return memo.getOrPut(key) { ruleImpl(ruleId, pos) }  // Fail cached too
    }
}
